import requests
from bs4 import BeautifulSoup

# Try searching for information about Janet Fish's artwork
search_url = 'https://www.google.com/search?q=Janet+Fish+Embroidery+from+Uzbekistan+2008+Dayton+Art+Institute+museum+catalog'

try:
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'
    }
    response = requests.get(search_url, headers=headers, timeout=15)

    if response.status_code == 200:
        soup = BeautifulSoup(response.text, 'html.parser')

        # Look for search results that might contain relevant information
        search_results = soup.find_all('div', class_='g')

        for result in search_results[:10]:  # Check first 10 results
            try:
                title = result.get_text().lower()
                if 'janet fish' in title and 'uzbekistan' in title:
                    link = result.find('a')
                    if link and 'href' in link.attrs:
                        href = link['href']
                        if href.startswith('/url?q='):
                            actual_url = href.split('/url?q=')[1].split('&')[0]
                            print(f'Potential relevant result: {actual_url}')
                            print(f'Title: {title[:100]}')
                            print()
            except:
                continue

    print('Google search completed.')
except Exception as e:
    print(f'Error with Google search: {e}')
""}

