import requests
from bs4 import BeautifulSoup

# Try to access Dayton Art Institute website directly
url = 'https://www.daytonartinstitute.org'

try:
    response = requests.get(url, timeout=10)
    if response.status_code == 200:
        soup = BeautifulSoup(response.text, 'html.parser')

        # Look for links related to collection, exhibitions, or Janet Fish
        links = soup.find_all('a', href=True)

        for link in links:
            href = link['href'].lower()
            text = link.get_text().lower()

            if any(keyword in href or keyword in text for keyword in ['collection', 'exhibition', 'janet fish', 'uzbekistan', 'past exhibits']):
                print(f'Found relevant link: {link.get_text()} -> {link[\"href\"]}')

        # Look for collection search functionality
        collection_links = [link for link in links if 'collection' in link.get_text().lower() or 'search' in link.get_text().lower()]
        if collection_links:
            print('\\nCollection/search links found:')
            for link in collection_links[:5]:
                print(f'  {link.get_text()} -> {link[\"href\"]}')

    else:
        print(f'Dayton Art Institute returned status: {response.status_code}')

except Exception as e:
    print(f'Error accessing Dayton Art Institute: {e}')
""}

