import requests
from bs4 import BeautifulSoup

# Try to access other major art museums and databases
museum_urls = [
    'https://www.metmuseum.org',
    'https://www.moma.org', 
    'https://www.artic.edu',
    'https://www.si.edu/museums',
    'https://www.tfaoi.com'
]

for url in museum_urls:
    try:
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            soup = BeautifulSoup(response.text, 'html.parser')

            # Look for search functionality
            search_forms = soup.find_all('form', action=True)
            search_links = soup.find_all('a', href=True)

            print(f'From {url}:')

            # Check for search forms
            for form in search_forms:
                if 'search' in form.get('action', '').lower():
                    print(f'  Search form found: {form.get(\"action\")}')

            # Check for search links
            search_links_found = [link for link in search_links if 'search' in link.get_text().lower()]
            if search_links_found:
                for link in search_links_found[:3]:
                    print(f'  Search link: {link.get_text()} -> {link.get(\"href\")}')

            print()
        else:
            print(f'{url} returned status: {response.status_code}')

    except Exception as e:
        print(f'Error accessing {url}: {e}')
""}

