import requests
from bs4 import BeautifulSoup
import json

# Try to access specific URLs that might contain information about Janet Fish's artwork
# and create a comprehensive report

urls_to_try = [
    'https://en.wikipedia.org/wiki/Janet_Fish',
    'https://www.wikiart.org/en/janet-fish',
    'https://www.artsy.net/artist/janet-fish',
    'https://www.saam.si.edu/artwork/embroidery-from-uzbekistan',  # Smithsonian American Art Museum
    'https://www.tfaoi.com/aa/11/aa-11-123.htm',  # Traditional Fine Arts Organization
    'https://www.artcyclopedia.com/artists/janet_fish.html',
    'https://www.janetfish.com',  # Artist's official website
    'https://www.daytonarts.org/news',  # Dayton arts news
    'https://www.daytondailynews.com/entertainment/arts',  # Dayton news arts section
]

print('Creating comprehensive search report for Janet Fish\'s \"Embroidery from Uzbekistan\"...')
print('=' * 70)

results = {}

for url in urls_to_try:
    try:
        print(f'Trying: {url}')
        response = requests.get(url, timeout=10)
        if response.status_code == 200:
            soup = BeautifulSoup(response.text, 'html.parser')
            text_content = soup.get_text().lower()

            # Check for relevant content
            relevant_terms = []

            if 'janet fish' in text_content:
                relevant_terms.append('janet fish')

            if 'embroidery from uzbekistan' in text_content:
                relevant_terms.append('embroidery from uzbekistan')

            if 'uzbekistan' in text_content:
                relevant_terms.append('uzbekistan')

            if any(fruit in text_content for fruit in ['fruit', 'apple', 'pear', 'orange', 'lemon', 'peach', 'plum', 'grape']):
                relevant_terms.append('fruit mentioned')

            if 'composition' in text_content or 'arrangement' in text_content:
                relevant_terms.append('composition/arrangement')

            if 'clockwise' in text_content:
                relevant_terms.append('clockwise')

            if relevant_terms:
                print(f'  FOUND: {relevant_terms}')

                # Extract paragraphs that might contain artwork descriptions
                paragraphs = soup.find_all('p')
                artwork_paragraphs = []

                for p in paragraphs:
                    p_text = p.get_text().lower()
                    if any(term in p_text for term in relevant_terms):
                        artwork_paragraphs.append(p.get_text().strip())

                if artwork_paragraphs:
                    print('  Artwork description paragraphs:')
                    for i, p in enumerate(artwork_paragraphs[:3]):
                        print(f'    {i+1}. {p[:150]}...')

                results[url] = {
                    'status': 'success',
                    'relevant_terms': relevant_terms,
                    'paragraphs': artwork_paragraphs[:3]  # Store first 3 paragraphs
                }
            else:
                print('  No obviously relevant content found')
                results[url] = {'status': 'no_relevant_content'}

        else:
            print(f'  Status: {response.status_code}')
            results[url] = {'status': f'http_error_{response.status_code}'}

    except Exception as e:
        print(f'  Error: {e}')
        results[url] = {'status': f'exception: {str(e)}'}

    print()

# Create a summary
print('=' * 70)
print('SEARCH SUMMARY:')
print('=' * 70)

successful_results = [url for url, data in results.items() if data.get('status') == 'success']
print(f'Successful access: {len(successful_results)} URLs')
print(f'Total URLs tried: {len(urls_to_try)}')

if successful_results:
    print('\\nSuccessful URLs:')
    for url in successful_results:
        data = results[url]
        print(f'  - {url}')
        print(f'    Relevant terms: {data[\"relevant_terms\"]}')
        if data.get('paragraphs'):
            print(f'    Paragraphs: {len(data[\"paragraphs\"])} found')

print('\\nSearch completed.')
""}

